  function escapeHtml(value) {
    return value.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  var BASE_STYLE = `
  *{box-sizing:border-box;margin:0;padding:0}
  body{font-family:system-ui,-apple-system,sans-serif;background:#111;color:#eee;padding:16px;max-width:480px;margin:0 auto}
  h1{font-size:1.25rem;margin-bottom:4px}
  h2{font-size:1rem;margin:16px 0 8px;color:#aaa}
  .card{background:#1d1d1d;border:1px solid #333;border-radius:10px;padding:12px;margin-bottom:8px}
  .muted{color:#888;font-size:.85rem}
  .pill{display:inline-block;font-size:.75rem;padding:2px 8px;border-radius:999px;background:#333;margin-left:6px}
  button{width:100%;padding:14px;font-size:1rem;border:0;border-radius:10px;margin-top:8px;cursor:pointer}
  .in{background:#1f6f43;color:#fff}
  .out{background:#8a2d2d;color:#fff}
  #msg{margin-top:10px;font-size:.9rem;color:#9ad}
`;
  function clockScript(tenantId2, token) {
    return `
  <script>
    const HEADERS = { 'content-type': 'application/json', 'x-tenant-id': ${JSON.stringify(tenantId2)}, 'x-employee-token': ${JSON.stringify(token)} };
    async function punch(action) {
      const res = await fetch(action, { method: 'POST', headers: HEADERS, body: '{}' });
      const body = await res.json();
      const msg = document.getElementById('msg');
      if (res.ok) { msg.textContent = action === 'clock-in' ? 'Clocked in.' : 'Clocked out.'; location.reload(); }
      else { msg.textContent = body.error ? body.error.message : 'error'; }
    }
  <\/script>`;
  }
  function clockButtons(clockedIn) {
    return clockedIn ? `<button class="out" onclick="punch('clock-out')">Clock Out</button>` : `<button class="in" onclick="punch('clock-in')">Clock In</button>`;
  }
  function dayPageHtml(input) {
    const { schedule } = input;
    const shifts = schedule.shifts.length === 0 ? '<p class="muted">No shifts scheduled.</p>' : schedule.shifts.map(
      (s2) => `<div class="card">${escapeHtml(s2.starts_at)} &rarr; ${escapeHtml(s2.ends_at)}${s2.notes ? `<div class="muted">${escapeHtml(s2.notes)}</div>` : ""}</div>`
    ).join("");
    const assignments = schedule.assignments.length === 0 ? '<p class="muted">No assignments today.</p>' : schedule.assignments.map(
      (a) => `<div class="card">${escapeHtml(a.title)}<span class="pill">${escapeHtml(a.kind)}</span><span class="pill">${escapeHtml(a.status)}</span>${a.scheduled_at ? `<div class="muted">${escapeHtml(a.scheduled_at)}</div>` : ""}</div>`
    ).join("");
    const clockedIn = schedule.openTimeEntry !== null;
    return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>My Day</title>
<style>${BASE_STYLE}</style>
</head>
<body>
<h1>My Day</h1>
<p class="muted">${escapeHtml(input.employeeName)} &middot; ${escapeHtml(schedule.date)}</p>
<h2>Shifts</h2>
${shifts}
<h2>Assignments</h2>
${assignments}
<h2>Time clock</h2>
<p class="muted">${clockedIn ? `Clocked in at ${escapeHtml(schedule.openTimeEntry.clock_in_at)}` : "Not clocked in."}</p>
${clockButtons(clockedIn)}
<div id="msg"></div>
${clockScript(input.tenantId, input.token)}
</body>
</html>`;
  }
  function clockPageHtml(input) {
    const clockedIn = input.clockedInAt !== null;
    return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Time Clock</title>
<style>${BASE_STYLE}</style>
</head>
<body>
<h1>Time Clock</h1>
<p class="muted">${escapeHtml(input.employeeName)}</p>
<div class="card">${clockedIn ? `Clocked in at ${escapeHtml(input.clockedInAt)}` : "Not clocked in."}</div>
${clockButtons(clockedIn)}
<div id="msg"></div>
${clockScript(input.tenantId, input.token)}
</body>
</html>`;
  }

