  // packages/industries/src/router.ts
  var applyBodySchema = external_exports.object({
    /** Optional audit actor (user id). Defaults to "system". */
    actor: external_exports.string().min(1).optional()
  }).strict();
  function industriesRouter(deps) {
    const app2 = new Hono2();
    app2.onError(errorHandler2);
    app2.use("*", tenantMiddleware(asCoreDb(deps.db)));
    app2.get("/", (c) => {
      const { limit, offset: offset2 } = parsePagination(c.req.query());
      const industries = listIndustries();
      return c.json({ data: industries.slice(offset2, offset2 + limit), limit, offset: offset2 });
    });
    app2.get("/applied", async (c) => {
      const applied = await getAppliedIndustry(deps.db, c.get("tenantId"));
      if (!applied) {
        throw ApiError.notFound("no industry applied for this tenant");
      }
      return c.json({ data: applied });
    });
    app2.get("/terminology", async (c) => {
      const terminology = await getTerminology(deps.db, c.get("tenantId"));
      if (!terminology) {
        throw ApiError.notFound("no industry applied for this tenant");
      }
      return c.json({ data: terminology });
    });
    app2.get("/:key", (c) => {
      const key2 = c.req.param("key");
      const config = getIndustryConfig(key2);
      if (!config) {
        throw ApiError.notFound(`unknown industry: ${key2}`);
      }
      return c.json({ data: config });
    });
    app2.post("/:key/apply", async (c) => {
      const text2 = await c.req.text();
      let body = {};
      if (text2.trim() !== "") {
        let parsed;
        try {
          parsed = JSON.parse(text2);
        } catch {
          throw ApiError.badRequest("request body must be valid JSON");
        }
        body = applyBodySchema.parse(parsed);
      }
      const applied = await applyIndustry(deps.db, c.get("tenantId"), c.req.param("key"), {
        events: deps.events,
        actor: body.actor,
        contracts: deps.contracts
      });
      return c.json({ data: applied });
    });
    return app2;
  }

