      const existingPayments = new Set(
        (await trx.selectFrom("retail_payments").select("source_id").where("tenant_id", "=", tenantId2).execute()).map((r) => r.source_id)
      );
      const existingOrders = new Set(
        (await trx.selectFrom("retail_order_lines").select("source_order_id").where("tenant_id", "=", tenantId2).groupBy("source_order_id").execute()).map((r) => r.source_order_id)
      );
      const existingRefunds = new Set(
        (await trx.selectFrom("retail_refunds").select("source_id").where("tenant_id", "=", tenantId2).execute()).map((r) => r.source_id)
      );
