    let unreconciledCount = 0;
    let totalDeltaCents = 0;
    for (const p of payouts) {
      const m = latestByPayout.get(p.id);
      if (!m) {
        unreconciledCount += 1;
        continue;
      }
      if (m.matched === 1) matchedCount += 1;
      else unmatchedCount += 1;
      totalDeltaCents += m.delta_cents;
    }
    const covStarts = payouts.map((p) => p.coverage_start ?? p.paid_at).filter((v) => v != null).sort();
    const covEnds = payouts.map((p) => p.coverage_end ?? p.paid_at).filter((v) => v != null).sort();
    const payoutCoverage = {
      start: covStarts.length > 0 ? covStarts[0] : null,
      end: covEnds.length > 0 ? covEnds[covEnds.length - 1] : null
    };
    const pmin = await db2.selectFrom("finance_payments").select((eb) => eb.fn.min("occurred_at").as("lo")).where("tenant_id", "=", tenantId2).executeTakeFirst();
    const pmax = await db2.selectFrom("finance_payments").select((eb) => eb.fn.max("occurred_at").as("hi")).where("tenant_id", "=", tenantId2).executeTakeFirst();
    const paymentsPeriod = { start: pmin?.lo ?? null, end: pmax?.hi ?? null };
    let partialCoverage = false;
    if (paymentsPeriod.start && paymentsPeriod.end) {
      if (!payoutCoverage.start || !payoutCoverage.end) {
        partialCoverage = true;
      } else if (payoutCoverage.start > paymentsPeriod.start || payoutCoverage.end < paymentsPeriod.end) {
        partialCoverage = true;
      }
    }
    return {
      payoutCount: payouts.length,
      matchedCount,
      unmatchedCount,
      unreconciledCount,
      totalDeltaCents,
      payoutCoverage,
      paymentsPeriod,
      partialCoverage
    };
